/* eslint-disable react/require-default-props */
import React, { ElementRef, useImperativeHandle, useRef } from 'react';
import * as AlertDialog from '@radix-ui/react-alert-dialog';
import { styled } from '@hexa-ui/theme';
import {
  ContentCSS,
  OverlayCSS,
  StyledDialogActions,
  StyledDialogBody,
  StyledDialogHeader,
  StyledDialogTitle,
  StyledCriticalLine,
} from '../utils/Dialog.styles';

const StyledOverlay = styled(AlertDialog.Overlay, OverlayCSS);
const StyledModalContent = styled(AlertDialog.AlertDialogContent, ContentCSS);

type OverlayProps = React.ComponentProps<typeof AlertDialog.Overlay> & {
  color?: 'dark' | 'light';
};

const Overlay = ({ color = 'dark' }: OverlayProps): JSX.Element => <StyledOverlay color={color} />;

const { Action, Cancel, Trigger } = AlertDialog;

export const ModalCancel = ({ children }: { children: React.ReactNode }): JSX.Element => (
  <Cancel asChild>{children}</Cancel>
);

export const ModalAction = ({ children }: { children: React.ReactNode }): JSX.Element => (
  <Action asChild>{children}</Action>
);

export type ModalProps = React.ComponentProps<typeof AlertDialog.Root> & {
  variant?: 'overlay' | 'bottomTray' | 'takeOver';
  destructive?: 'critical' | 'off';
  onEscapeKeyDown?: (event: KeyboardEvent) => void;
  headerImage?: React.ReactNode;
  headerHeight?: string;
  trigger?: React.ReactNode;
  title?: React.ReactNode;
  actions: React.ReactNode;
};

export const Modal = React.forwardRef<ElementRef<typeof StyledModalContent>, ModalProps>(
  (
    {
      children,
      variant = 'overlay',
      destructive = 'off',
      onEscapeKeyDown,
      headerImage,
      headerHeight,
      title,
      actions,
      trigger,
      ...props
    },
    forwardedRef
  ): JSX.Element => {
    const innerRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(forwardedRef, () => innerRef?.current as HTMLDivElement);

    return (
      <AlertDialog.Root {...props}>
        {trigger && <Trigger asChild>{trigger}</Trigger>}
        <Overlay id="overlay" />
        <StyledModalContent variant={variant} onEscapeKeyDown={onEscapeKeyDown} ref={innerRef}>
          {destructive === 'critical' && <StyledCriticalLine data-testid="destructive" />}
          {(headerImage || title) && (
            <StyledDialogHeader
              image={Boolean(headerImage)}
              css={{ ...(headerHeight && { height: `${headerHeight}` }) }}
            >
              {headerImage}
              {title && (
                <StyledDialogTitle shouldAdjustPadding={!headerImage}>{title}</StyledDialogTitle>
              )}
            </StyledDialogHeader>
          )}
          <StyledDialogBody adjustTopPadding={!headerImage && !title} adjustRightPadding={false}>
            {children}
          </StyledDialogBody>
          {actions && <StyledDialogActions>{actions}</StyledDialogActions>}
        </StyledModalContent>
      </AlertDialog.Root>
    );
  }
);
